import {hero,robot,icon as oldIcon} from './art.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={play:'<path d="m8 5 11 7-11 7z"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',step:'<path d="m5 5 9 7-9 7zM18 5v14"/>',reset:'<path d="M4 10a8 8 0 1 1 2 8M4 4v6h6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3h.01"/>',sound:'<path d="M3 9h4l5-5v16l-5-5H3zm13-2c4 3 4 7 0 10m3-13c6 5 6 11 0 16"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16m6-14v16"/>',code:'<path d="m7 6-6 6 6 6m10-12 6 6-6 6M14 3l-4 18"/>',back:'<path d="M20 12H4m7-7-7 7 7 7"/>',down:'<path d="M12 4v16m-6-6 6 6 6-6"/>',up:'<path d="M12 20V4m-6 6 6-6 6 6"/>',left:'<path d="M20 12H4m7-6-7 6 7 6"/>',right:'<path d="M4 12h16m-7-6 7 6-7 6"/>',check:'<path d="m4 12 5 5L20 6"/>',gear:'<path d="m10 2 4 0 1 4 4 1 2 4-3 3 0 4-4 1-2 3-4-2-4 0-1-4-2-3 3-3 1-4z"/><circle cx="12" cy="12" r="3"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 17v4h18v-4"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M3 17v4h18v-4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',game:'<path d="M7 6h10c4 0 6 13 3 14-2 1-4-4-4-4H8s-2 5-4 4C1 19 3 6 7 6zM6 9v5m-2-2h5m7-2h.01m3 3h.01"/>',spark:'<path d="m12 2 2 7 7 3-7 2-2 8-3-8-7-2 7-3z"/>',book:'<path d="M3 4q5-2 9 1 4-3 9-1v16q-5-2-9 1-4-3-9-1zM12 5v16"/>',box:'<path d="m3 7 9-5 9 5v11l-9 4-9-4zM3 7l9 4 9-4M12 11v11"/>'};
export function icon(name){return paths[name]?`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`:oldIcon(name);}
export const MARKERS=[[115,310],[235,285],[340,330],[450,300],[555,330],[770,300],[820,205],[640,160],[450,155],[245,155]];
export const tree=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 8v34" stroke="#547762" stroke-width="9" stroke-linecap="round"/><path d="M-24 9q-9-19 5-30 0-24 21-24 27-2 28 22 22 13 6 33-19 14-36 5-15 10-24-6" fill="#8CAA83"/><path d="M0 14V-14m0 20 14-11" stroke="#708F73" stroke-width="3" fill="none" stroke-linecap="round"/></g>`;
export function building(x,y,name='workshop',ready=false,s=1){
 const roof=name==='beacon'?`<path d="M34 5h34l-5 25H39z" fill="${ready?'#F6D46C':'#A5B7A0'}"/><path d="m50 5 0-17m-8 0h16" stroke="#14353B" stroke-width="4"/>`:`<path d="m-1 36 51-35 52 35z" fill="${ready?'#EF733E':'#86A78F'}"/>`;
 return `<g transform="translate(${x} ${y}) scale(${s})"><ellipse cx="50" cy="104" rx="62" ry="9" fill="#14353B" opacity=".1"/><rect x="8" y="30" width="84" height="72" rx="9" fill="#F8F5EC" stroke="#547762" stroke-width="3"/>${roof}<rect x="39" y="64" width="23" height="38" rx="9" fill="#14353B"/><rect x="19" y="47" width="17" height="20" rx="4" fill="${ready?'#F6D46C':'#BED3C0'}"/><rect x="66" y="47" width="16" height="20" rx="4" fill="${ready?'#F6D46C':'#BED3C0'}"/>${ready?'<circle cx="83" cy="23" r="13" fill="#126B62"/><path d="m77 23 4 4 7-8" fill="none" stroke="#fffdf7" stroke-width="3" stroke-linecap="round"/>':''}</g>`;
}
export function atlas(path,completed={}){
 const prefix=path==='foundation'?'F':path==='python'?'P':'C';
 const route=MARKERS.map(([x,y])=>`${x},${y}`).join(' ');
 return `<svg viewBox="0 0 1000 490" class="atlas-art" aria-hidden="true"><defs><pattern id="waves" width="95" height="62" patternUnits="userSpaceOnUse"><path d="M8 35q15 8 30 0m18-23q15 8 30 0" fill="none" stroke="#A6CBD0" stroke-width="3" stroke-linecap="round"/></pattern></defs><rect width="1000" height="490" rx="22" fill="#91BDC7"/><rect width="1000" height="490" rx="22" fill="url(#waves)"/><path d="M48 260Q1 158 122 114q-18-77 116-66 82-69 176-22 100-42 179 27 115-45 166 32 160-25 187 102 70 121-55 178 8 87-132 73-68 79-174 13-151 58-231-7-107 43-168-31-144 33-138-69Z" fill="#BBCFB0" stroke="#D7E2C5" stroke-width="14"/><path d="M174 420q57-26 91 4m450-6q66 4 84-37" fill="none" stroke="#A2BB97" stroke-width="8" stroke-linecap="round"/><polyline points="${route}" fill="none" stroke="#E8DFB9" stroke-width="43" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${route}" fill="none" stroke="#F8F5EC" stroke-opacity=".7" stroke-width="3" stroke-dasharray="5 12" stroke-linecap="round"/>${[[94,192,.9],[185,370,.7],[360,95,.9],[550,95,.75],[708,87,1.1],[900,235,.9],[745,385,.8],[405,395,.8],[330,237,.5],[613,259,.7],[855,370,.7]].map(t=>tree(...t)).join('')}${building(100,70,'workshop',!!completed[prefix+(path==='foundation'?1:11)],.65)}${building(860,100,'beacon',Object.keys(completed).length>5,.8)}<g transform="translate(514 213)"><path d="M-36 4q40-22 81 0v23q-40-22-81 0Z" fill="#E8DFB9" stroke="#547762" stroke-width="3"/><path d="M-36 0v31m81-31v31M-18-4v24M0-8v24m22-23v25" stroke="#9C784D" stroke-width="4" stroke-linecap="round"/></g><g fill="#F8F5EC" opacity=".6"><ellipse cx="45" cy="65" rx="44" ry="13"/><ellipse cx="899" cy="439" rx="55" ry="14"/></g><g fill="#F6D46C"><path d="m685 336 4 8 9 1-7 6 2 9-8-4-8 4 2-9-7-6 9-1z"/><path d="m352 179 3 7 8 1-6 5 2 8-7-4-7 4 1-8-5-5 8-1z"/></g><text x="515" y="469" text-anchor="middle" fill="#14353B" font-family="Arial" font-size="13" letter-spacing="4">${path==='foundation'?'WORKSHOP':path==='python'?'WILDWOOD':'BEACON'} ISLAND</text></svg>`;
}
const nested=(svg,x,y,width,height)=>svg.replace('<svg ',`<svg x="${x}" y="${y}" width="${width}" height="${height}" `).replace('role="img"','aria-hidden="true"');
export function worldSvg(w,appearance){
 const point=(x,y)=>[50+x*70,35+y*56];
 let objects='',details='';
 if(w.kind==='route'){
  const [gx,gy]=point(...w.goal);objects+=`<rect x="${gx-23}" y="${gy-18}" width="46" height="46" rx="12" fill="#F6D46C" stroke="#14353B" stroke-width="3"/><path d="m${gx+2} ${gy-12}-10 20h10l-4 14 15-23h-10l4-11Z" fill="#126B62"/>`;
 }
 if(w.kind==='bridge')objects+=`<g transform="translate(${(w.bridgeX??270)-270} 0)"><path d="M270 0q-25 115 0 185t0 175h95q-25-113 0-175T365 0Z" fill="#91BDC7"/><path d="M245 190h145" stroke="${w.bridgeStage>=2?'#DDBA70':'#A9BBA3'}" stroke-width="35" stroke-dasharray="${w.bridgeStage>=2?'0':'12 10'}"/><path d="M255 162v59m124-59v59" stroke="${w.bridgeStage>=1?'#86643C':'#AFBEA6'}" stroke-width="10" stroke-linecap="round"/>${w.bridgeStage===3?'<path d="m300 147 13 13 23-25" fill="none" stroke="#126B62" stroke-width="7" stroke-linecap="round"/>':''}</g>`;
 if(['garden','signals'].includes(w.kind))for(let i=0;i<w.count;i++){const [x,y]=point(i,2),on=(w.kind==='garden'?w.watered:w.lit).includes(i);objects+=w.kind==='garden'?`<g transform="translate(${x} ${y})"><ellipse cy="18" rx="22" ry="9" fill="#A88F64"/><path d="M0 17V-8m0 10q-30-1-20-23Q-1-20 0 2m0-8q0-28 23-26 2 24-23 26" fill="${on?'#126B62':'#A4AE88'}" stroke="${on?'#126B62':'#7C8F6F'}" stroke-width="3" stroke-linecap="round"/>${on?'<circle cx="0" cy="-17" r="8" fill="#F6D46C"/>':''}<text y="44" text-anchor="middle" font-size="16">${i}</text></g>`:`<g transform="translate(${x} ${y})"><path d="M0 25v-35" stroke="#547762" stroke-width="7"/><rect x="-18" y="-35" width="36" height="38" rx="10" fill="#14353B"/><circle cy="-16" r="10" fill="${on?'#F6D46C':'#8CAA83'}"/><text y="49" text-anchor="middle" font-size="16">${i}</text></g>`;}
 if(['repair','district','workshop','sandbox'].includes(w.kind))objects+=(w.parts??[]).map((p,i)=>building(70+i*130,60,p,w.repaired.includes(p),.85)+`<text x="${112+i*130}" y="174" text-anchor="middle" font-family="Arial" font-size="15">${esc(p)}</text>`).join('');
 if(w.kind==='workshop')objects+=`<g transform="translate(115 228)">${Array.from({length:Math.max(0,w.stock-w.collected)},(_,i)=>`<rect x="${i*30}" y="0" width="22" height="35" rx="5" fill="#F6D46C" stroke="#91661E" stroke-width="2"/><path d="M${i*30+7} 12h8m-4-4v8" stroke="#91661E" stroke-width="2"/>`).join('')}<text x="75" y="58" text-anchor="middle" font-size="15">${w.collected} cells collected</text></g>`;
 if(['gate','cells','beacon','workshop','district','sandbox'].includes(w.kind)){
   const pct=Math.min(1,w.power/(w.targetPower||10));details+=`<g transform="translate(380 235)"><rect width="190" height="60" rx="16" fill="#FFFDF7" stroke="#547762" stroke-width="2"/><rect x="12" y="13" width="115" height="30" rx="8" fill="#D9EEE1"/><rect x="12" y="13" width="${115*pct}" height="30" rx="8" fill="#F6D46C"/><text x="153" y="35" text-anchor="middle" font-family="Arial" font-size="20" font-weight="bold">${w.power}/${w.targetPower??10}</text></g>`;
   if(w.kind==='gate'||w.kind==='workshop')objects+=`<g transform="translate(300 70)"><path d="M-40 80V-10m80 90V-10" stroke="#547762" stroke-width="12" stroke-linecap="round"/><rect x="-38" y="0" width="76" height="${w.gateOpen?10:75}" rx="6" fill="${w.gateOpen?'#F6D46C':'#126B62'}"/><path d="M-17 20h34m-34 20h34" stroke="#D9EEE1" stroke-width="5" opacity="${w.gateOpen?0:1}"/></g>`;
 }
 if(w.kind==='message')objects+=`${building(390,75,'beacon',!!w.message,1)}<rect x="73" y="65" width="300" height="100" rx="20" fill="#FFFDF7" stroke="#547762" stroke-width="2"/><text x="223" y="118" text-anchor="middle" font-family="Arial" font-size="16">${esc(w.message.slice(-31)||'…')}</text>`;
 if(w.kind==='branch'){
   objects+=['left','right'].map((d,i)=>{const x=50+(i?(w.rightX??6):(w.leftX??1))*70;return `<path d="M300 290 Q${x} 240 ${x} 100" stroke="${w.route===d?'#F6D46C':'#E8DFB9'}" stroke-width="35" fill="none" stroke-linecap="round"/>`;}).join('');
   if(w.path==='python')objects+=['hospital','school','workshop'].map((p,i)=>building(120+i*160,65,p,w.route===p,.7)+`<text x="${155+i*160}" y="152" text-anchor="middle" font-family="Arial" font-size="15">${p}</text>`).join('');
   else {const left=50+(w.leftX??1)*70,right=50+(w.rightX??6)*70;objects+=`<text x="${left}" y="75" text-anchor="middle" font-size="18">left</text><text x="${right}" y="75" text-anchor="middle" font-size="18">right</text>${w.sensor==='blocked'?tree(left,145,.75):`<path d="m${left-20} 140 14 14 24-29" stroke="#126B62" stroke-width="7" fill="none" stroke-linecap="round"/>`}`;}
 }
 if(w.kind==='lift')objects+=`<rect x="365" y="15" width="140" height="285" rx="15" fill="#F8F5EC" stroke="#547762" stroke-width="4"/>${Array.from({length:6},(_,i)=>`<path d="M365 ${280-i*44}h140" stroke="#A5B7A0" stroke-width="2"/><text x="520" y="${280-i*44}" font-size="17">${i}</text>`).join('')}<rect x="381" y="${247-w.floor*44}" width="108" height="36" rx="8" fill="#EF733E"/><text x="435" y="${272-w.floor*44}" text-anchor="middle" fill="#14353B" font-size="18">${w.floor}</text>`;
 if(w.kind==='robot')details+=`<rect x="290" y="70" width="270" height="110" rx="20" fill="#FFFDF7"/><text x="315" y="108" font-size="23" font-weight="bold">${esc(w.robotName)}</text><text x="315" y="145" font-size="18">Energy ${w.robotEnergy} · ${w.robotReady?'✓ Ready':'… Waiting'}</text>`;
 if(w.kind==='arithmetic')objects+=`<g transform="translate(230 70)">${Array.from({length:w.panels},(_,i)=>`<rect x="${(i%3)*70}" y="${Math.floor(i/3)*55}" width="56" height="40" rx="8" fill="#8CAA83" stroke="#547762" stroke-width="2"/>`).join('')}</g><text x="330" y="245" text-anchor="middle" font-family="Arial" font-size="23">${w.supplies} cells sent${w.checkEnergy?' · '+w.robotEnergy+' energy left':''}</text>`;
 if(w.kind==='delivery')objects+=(w.items??[]).map((p,i)=>`<g transform="translate(${200+i*75} 110)"><rect x="-23" y="-25" width="46" height="47" rx="10" fill="${i<w.delivered.length?'#F6D46C':'#E8DFB9'}" stroke="#547762" stroke-width="2"/><path d="M-23-9h46M0-25v47" stroke="#A88F64" stroke-width="3"/><text y="48" text-anchor="middle" font-size="13">${esc(p)}</text>${i<w.delivered.length?'<path d="m-8-2 5 5 11-12" stroke="#126B62" stroke-width="4" fill="none"/>':''}</g>`).join('');
 const [px,py]=point(w.x,w.y);
 return `<svg viewBox="0 0 640 350" role="img" aria-label="${esc(worldDescription(w))}"><rect width="640" height="350" rx="18" fill="#DCEADD"/><path d="M0 284q200-35 330 0t310-9v75H0Z" fill="#CBDCC0"/><g opacity=".55">${Array.from({length:5},(_,y)=>Array.from({length:8},(_,x)=>{const [px,py]=point(x,y);return `<rect x="${px-28}" y="${py-24}" width="56" height="48" rx="12" fill="${w.blocked?.some(p=>p[0]===x&&p[1]===y)?'#91BDC7':'#E8DFB9'}"/>`;}).join('')).join('')}</g>${objects}${details}${nested(robot(),px-28,py-43,56,68)}${nested(hero(appearance.suit,appearance.emblem,appearance.cape),10,232,72,88)}${tree(605,62,.55)}<g fill="#F8F5EC"><circle cx="54" cy="309" r="3"/><circle cx="600" cy="306" r="3"/></g></svg>`;
}
export function worldDescription(w){return `Pip at column ${w.x}, row ${w.y}. Power ${w.power}. ${w.gateOpen?'Gate open. ':''}${w.watered.length} plants watered. ${w.lit.length} signals lit. Repaired: ${w.repaired.join(', ')||'none'}. Delivered ${w.delivered.length} parcels. ${w.message||''}`;}
